/*
 * microvium_port.h -- customized for STM32L433RC (Cortex-M4, 64KB SRAM total)
 *
 * Derived from microvium_port_example.h (generated by `microvium --generate-lib`).
 * Only the following values were changed from the example; everything else is
 * the vendor default. See microvium_port_example.h in this same folder for
 * the full explanation of every setting if you need to tune something else.
 *
 * --- How to size MVM_STACK_SIZE / MVM_MAX_HEAP_SIZE for YOUR script ---
 * This board has 64KB of SRAM total, shared between: the C stack (1KB,
 * reserved in linker/STM32L433RCTX_FLASH.ld as _Min_Stack_Size), all C
 * static/global variables (.data + .bss, currently just a few HAL structs --
 * tens of bytes), the newlib malloc heap (grows on demand via sbrk, see
 * Core/Src/sysmem.c), and everything below. Concretely:
 *   1. Build the firmware (`make`) and check the final RAM usage printed by
 *      `arm-none-eabi-size build/firmware.elf` (the "data + bss" column).
 *   2. Subtract that (plus the 1KB C stack) from 64KB to see how much is
 *      actually free for the VM + malloc heap.
 *   3. agent.mvm.js here is a tiny 2-state state machine with no closures,
 *      arrays, or recursion, so 256 bytes of VM stack and roughly 1-2KB of
 *      VM heap is already generous. If you add more script logic (arrays,
 *      objects, more variables) and start seeing MVM_E_OUT_OF_MEMORY or
 *      MVM_E_STACK_OVERFLOW, raise MVM_MAX_HEAP_SIZE / MVM_STACK_SIZE first.
 */
#pragma once

#include <stdbool.h>
#include <string.h>
#include <assert.h>
#include <stdint.h>

#define MVM_PORT_VERSION 1

/* Small and simple script (one state machine, no deep call chains). */
#define MVM_STACK_SIZE 256

#define MVM_ALLOCATION_BUCKET_SIZE 256

/*
 * Conservative default for a 64KB-SRAM part. See the sizing notes above
 * before raising this.
 */
#define MVM_MAX_HEAP_SIZE 2048

#define MVM_NATIVE_POINTER_IS_16_BIT 0

/* JS numeric literals (e.g. 3000, timestamps) need float64 support. */
#define MVM_SUPPORT_FLOAT 1

#if MVM_SUPPORT_FLOAT
#define MVM_FLOAT64 double
#define MVM_FLOAT64_NAN ((MVM_FLOAT64)(INFINITY * 0.0))
#endif // MVM_SUPPORT_FLOAT

/* Keep safety checks on for this demo; they cost flash/speed but catch bugs
 * early. Consider turning both off once the firmware is well-tested. */
#define MVM_SAFE_MODE 1
#define MVM_DONT_TRUST_BYTECODE 1

#define MVM_VERY_EXPENSIVE_MEMORY_CHECKS 0

#define MVM_LONG_PTR_TYPE void*
#define MVM_LONG_PTR_NEW(p) ((MVM_LONG_PTR_TYPE)p)
#define MVM_LONG_PTR_TRUNCATE(p) ((void*)p)
#define MVM_LONG_PTR_ADD(p, s) ((MVM_LONG_PTR_TYPE)((uint8_t*)p + (intptr_t)s))
#define MVM_LONG_PTR_SUB(p2, p1) ((int16_t)((uint8_t*)p2 - (uint8_t*)p1))

#define MVM_READ_LONG_PTR_1(lpSource) (*((uint8_t *)lpSource))
#define MVM_READ_LONG_PTR_2(lpSource) (*((uint16_t *)lpSource))

#define MVM_LONG_MEM_CMP(p1, p2, size) memcmp(p1, p2, size)
#define MVM_LONG_MEM_CPY(target, source, size) memcpy(target, source, size)

/*
 * Fatal VM errors call Error_Handler() (main.c), which parks the MCU in an
 * infinite loop with interrupts disabled -- easy to spot on a debugger/LED,
 * and guarantees (per the port contract) that control never returns to the
 * VM after a fatal error.
 */
void Error_Handler(void);
#define MVM_FATAL_ERROR(vm, e) (Error_Handler())

#define MVM_ALL_ERRORS_FATAL 0

#define MVM_SWITCH(tag, upper) switch (tag)
#define MVM_CASE(value) case value

#define MVM_CHECK_CRC16_CCITT(lpData, size, expected) (default_crc16(lpData, size) == expected)

/*
 * We only ever restore a bytecode image baked in at compile time (see
 * tools/gen_bytecode_header.sh) -- we never need to create a snapshot or
 * attach a debugger on-device, so both capabilities are disabled to save
 * flash space.
 */
#define MVM_INCLUDE_SNAPSHOT_CAPABILITY 0
#define MVM_INCLUDE_DEBUG_CAPABILITY 0

#define MVM_USE_SINGLE_RAM_PAGE 0

#define MVM_CONTEXTUAL_MALLOC(size, context) MVM_MALLOC(size)
#define MVM_CONTEXTUAL_FREE(ptr, context) MVM_FREE(ptr)
